# Example code snippet to check for safe YAML loading
import yaml

def safe_yaml_load(yaml_string: str):
    try:
        data = yaml.safe_load(yaml_string)
        print(data)
    except yaml.YAMLError as e:
        print(f'Error: {e}')

# Test the function with a sample YAML string
safe_yaml_load("key: value")
